    string s;
    cin >> s;
    int count = 0;
    int n = s.length();
    if (n == 0) {
        cout << 0 << endl;
        return 0;
    }
    char prev = s[0];
    int run_length = 1;
    for (int i = 1; i < n; i++) {
        if (s[i] == prev) {
            run_length++;
        } else {
            if (run_length % 2 == 0) {
                count++;
            }
            prev = s[i];
            run_length = 1;
        }
    }
    if (run_length % 2 == 0) {
        count++;
    }
    cout << count << endl;
    return 0;
}
